import sys

def check_num(field, maxval):
    if len(field) == 0:
        return ('empty', 0)
    for i, c in enumerate(field):
        if not c.isdigit():
            return ('digit', i)
    v = int(field)
    if v > maxval:
        return ('range', 0)
    return ('ok', v)

def check_price(field):
    if len(field) == 0:
        return ('empty', 0)
    for i, c in enumerate(field):
        if not (c.isdigit() or c == '.'):
            return ('digit', i)
    if field.count('.') != 1:
        return ('format', 0)
    dot = field.index('.')
    before = field[:dot]
    after = field[dot+1:]
    if len(before) < 1 or len(after) != 2:
        return ('format', 0)
    cents = int(before) * 100 + int(after)
    if cents > 9223372036854775807:
        return ('range', 0)
    return ('ok', cents)

def process(line):
    parts = line.split(',')
    if len(parts) < 3:
        return f"err {{LN}} {len(line)+1} missing"
    if len(parts) > 3:
        # find column of third comma
        idx = -1
        count = 0
        for i, c in enumerate(line):
            if c == ',':
                count += 1
                if count == 3:
                    idx = i
                    break
        return f"err {{LN}} {idx+1} extra"
    idf, qtyf, pricef = parts
    start_id = 0
    start_qty = len(idf) + 1
    start_price = len(idf) + 1 + len(qtyf) + 1

    kind, val = check_num(idf, 4294967295)
    if kind != 'ok':
        col = start_id + val + 1 if kind == 'digit' else start_id + 1
        return f"err {{LN}} {col} {kind}"
    idv = val
    kind, val = check_num(qtyf, 65535)
    if kind != 'ok':
        col = start_qty + val + 1 if kind == 'digit' else start_qty + 1
        return f"err {{LN}} {col} {kind}"
    qtyv = val
    kind, val = check_price(pricef)
    if kind != 'ok':
        col = start_price + val + 1 if kind == 'digit' else start_price + 1
        return f"err {{LN}} {col} {kind}"
    cents = val
    return f"ok {idv} {qtyv} {cents}"

def main():
    data = sys.stdin.buffer.read()
    if data.endswith(b'\n'):
        data = data[:-1]
    if data == b'':
        lines = []
    else:
        lines = data.split(b'\n')
    out = []
    for i, lb in enumerate(lines):
        line = lb.decode('latin1')
        res = process(line).replace("{LN}", str(i+1))
        out.append(res)
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

main()
